/// <summary>
/// designed by AVANADE
/// </summary>
/// <param name = "sender">FormControl</param>
/// <param name = "e">FormControlEventArgs</param>
[SuppressBPWarning('BPParameterNotUsed', 'Parameter e required in signature'),
    FormControlEventHandler(formControlStr(CredManCreditLimitCustGroup, AVAHeaderDescription_Description), FormControlEventType::Modified)]
public static void AVAHeaderDescription_Description_OnModified(FormControl sender, FormControlEventArgs e)
{
    CredManCreditLimitCustGroup custGroup = sender.formRun().dataSource(formDataSourceStr(CredManCreditLimitCustGroup,CredManCreditLimitCustGroup)).cursor();
    FormStringControl   editableDescription = sender;
    custGroup.description = editableDescription.text();
}

/// <summary>
/// designed by AVANADE
/// </summary>
/// <param name = "sender">FormDataSource</param>
/// <param name = "e">FormDataSourceEventArgs</param>
[SuppressBPWarning('BPParameterNotUsed', 'Parameter e required in signature'),
    FormDataSourceEventHandler(formDataSourceStr(CredManCreditLimitCustGroup, CredManCreditLimitCustGroup), FormDataSourceEventType::Activated)]
public static void CredManCreditLimitCustGroup_OnActivated(FormDataSource sender, FormDataSourceEventArgs e)
{
    FormStringControl   editableDescription;
    CredManCreditLimitCustGroup custGroup = sender.cursor();
    editableDescription = sender.formRun().design().controlName(formControlStr(CredManCreditLimitCustGroup, AVAHeaderDescription_Description));
    editableDescription.text(custGroup.description);

}

/// <summary>
/// AVA/WEN/2024/11/19         AVA_012782_UpdateCreditLimitGroupValues
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[   SuppressBPWarning('BPParameterNotUsed', 'Parameter e required in signature'),
    FormControlEventHandler(formControlStr(CredManCreditLimitCustGroup, AVAUpdateCreditLimitGroup), FormControlEventType::Clicked)]
public static void AVAUpdateCreditLimitGroup_OnClicked(FormControl sender, FormControlEventArgs e)
{
    FormRun formRun = sender.formRun();

    CredManCreditLimitCustGroup custGroup = formrun.dataSource(formDataSourceStr(CredManCreditLimitCustGroup,CredManCreditLimitCustGroup)).cursor();
    CredManCreditLimitCustGroupLine custGroupLine;
    AVACreditLimitGroupValues groupValues;

    while select custGroupLine where custGroupLine.CreditLimitCustGroup == custGroup.RecId
    {
        select firstonly groupValues where groupValues.CredManCreditLimitId == custGroup.CreditLimitId
            && groupValues.CustAccount == custGroupLine.CustAccount;
        if (!groupValues)
        {
            ttsbegin;
            custGroupLine.avaCreateGroupValuesCalculation();
            ttscommit;
        }
    }

}
